def build():
    questions=[]
    for n,line in enumerate(DATA.splitlines(),1):
        engine,topic,command,output,prompt,correct,bad1,bad2,technical,risk,impact,control=line.split('|')
        b1,why1=bad1.split('~');b2,why2=bad2.split('~')
        choices=[{'id':'a','text':correct},{'id':'b','text':b1},{'id':'c','text':b2}]
        random.Random(550029+n).shuffle(choices)
        explanation=f'✅ Doğru yanıt\n{correct}\n\n🔧 Teknik gerekçe\n{technical}\n\n⚠️ Risk\n{risk}\n\n💼 İş etkisi\n{impact}\n\n🛡️ Önerilen kontrol\n{control}\n\n❌ Diğer yanıtların değerlendirmesi\n• {b1}: {why1}.\n• {b2}: {why2}.'
        questions.append(dict(external_id=f'database-auditor-v1-{n:03}',number=n,chapter=(n-1)//11+1,engine=engine,topic=topic,kind='image',prompt=prompt,context=f'NovaTek veritabanı denetimindesin. Selin (Denetim Yöneticin) ve Derya (DBA) ile kanıt DB-{n:03} üzerinde çalışıyorsun. Platform: {ENGINES[engine]}. Görseli incele, kanıtın kapsamına göre karar ver. Ekran kurgusal eğitim kanıtıdır; üretimde sorgu çalıştırman gerekmez.',options=choices,answer=['a'],explanation=explanation,hint='Önce ekranın hangi sistem/nesne/oturumu kapsadığını ve onaylı kriteri ayır; ayar, gerçek kullanım ve kontrol sonucu aynı kanıt değildir.',difficulty='beginner' if n<=22 else 'intermediate' if n<=44 else 'advanced',goals=[topic,ENGINES[engine]],base_xp=10,published=True,premium=True,order=n,card_pages=[],image=f'database-auditor/screen_{n:03}.png',evidence={'command':command,'output':output.replace('\\n','\n'),'engine':ENGINES[engine]},technical=technical,risk=risk,impact=impact,control=control))
    assert len(questions)==55,len(questions)
    assert len({q['topic'] for q in questions})==55
    package={'slug':'database-auditor-v1','title':'Veritabanı Denetimi','description':'55 özgün görselli ve uygulamalı denetim kararı • 5 bölüm\nPostgreSQL, MySQL, Microsoft SQL Server ve Oracle. Erişim, ayrıcalık, şifreleme, bütünlük, log, yedek, yama ve izleme kontrollerini gerçekçi kanıtlardan öğren. Her yanıtta teknik gerekçe, risk, iş etkisi ve önerilen kontrol.','modules':MODULES,'engines':ENGINES,'questions':questions}
    (ROOT/'package.json').write_text(json.dumps(package,ensure_ascii=False,indent=2)+'\n')
    print('55 original cases:',{engine:sum(q['engine']==engine for q in questions) for engine in ENGINES})
if __name__=='__main__':build()
